COMMENT ON TABLE kyc_risk_assessment IS 'Customer risk rating with its factors (country, product, channel, occupation, PEP, behaviour). Append-only.';
COMMENT ON COLUMN kyc_risk_assessment.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN kyc_risk_assessment.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN kyc_risk_assessment.created_at IS 'Creation time';
COMMENT ON COLUMN kyc_risk_assessment.created_by IS 'Principal that created the row';
COMMENT ON COLUMN kyc_risk_assessment.kyc_profile_id IS 'KYC profile';
COMMENT ON COLUMN kyc_risk_assessment.customer_id IS 'Customer';
COMMENT ON COLUMN kyc_risk_assessment.model_version IS 'Risk model version';
COMMENT ON COLUMN kyc_risk_assessment.score IS 'Score 0..1000';
COMMENT ON COLUMN kyc_risk_assessment.risk_level IS 'Resulting level';
COMMENT ON COLUMN kyc_risk_assessment.factors IS 'Factor contributions and inputs';
COMMENT ON COLUMN kyc_risk_assessment.override_level IS 'Manual override';
COMMENT ON COLUMN kyc_risk_assessment.override_reason IS 'Reason for override';
COMMENT ON COLUMN kyc_risk_assessment.assessed_by IS 'Analyst for manual assessments';
COMMENT ON COLUMN kyc_risk_assessment.trigger IS 'Why the assessment ran';
COMMENT ON COLUMN kyc_risk_assessment.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_risk_assessment.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_risk_assessment.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_risk_assessment.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_risk_assessment.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_kyc_risk_assessment_tenant ON kyc_risk_assessment (tenant_id, created_at);
CREATE INDEX ix_kyc_risk_assessment_kyc_profile_id ON kyc_risk_assessment (kyc_profile_id);
CREATE INDEX ix_kyc_risk_assessment_customer_id ON kyc_risk_assessment (customer_id);
CREATE INDEX ix_kyc_risk_assessment_assessed_by ON kyc_risk_assessment (assessed_by);
ALTER TABLE kyc_risk_assessment ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON kyc_risk_assessment USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_kyc_risk_assessment_append_only BEFORE UPDATE OR DELETE ON kyc_risk_assessment FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- kyc_review: Periodic or event-driven KYC review (refresh) of a customer
CREATE TABLE kyc_review (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  kyc_profile_id               uuid NOT NULL REFERENCES kyc_profile(id),
  customer_id                  uuid NOT NULL,
  trigger                      varchar(40) NOT NULL CHECK (trigger IN ('PERIODIC', 'DOCUMENT_EXPIRY', 'RISK_CHANGE', 'SCREENING_HIT', 'CUSTOMER_CHANGE', 'REGULATOR_REQUEST', 'MANUAL')),
  status                       varchar(40) NOT NULL DEFAULT 'SCHEDULED' CHECK (status IN ('SCHEDULED', 'DUE', 'IN_PROGRESS', 'COMPLETED', 'OVERDUE', 'CANCELLED')),
  due_date                     date NOT NULL,
  assigned_to                  uuid,
  customer_outreach_at         timestamptz,
  outcome                      varchar(40),
  outcome_notes                text,
  completed_at                 timestamptz,
  restrictions_applied         jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE kyc_review IS 'Periodic or event-driven KYC review (refresh) of a customer';
COMMENT ON COLUMN kyc_review.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN kyc_review.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN kyc_review.created_at IS 'Creation time';
COMMENT ON COLUMN kyc_review.created_by IS 'Principal that created the row';
COMMENT ON COLUMN kyc_review.updated_at IS 'Last update time';
COMMENT ON COLUMN kyc_review.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN kyc_review.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN kyc_review.kyc_profile_id IS 'KYC profile';
COMMENT ON COLUMN kyc_review.customer_id IS 'Customer';
COMMENT ON COLUMN kyc_review.trigger IS 'Trigger';
COMMENT ON COLUMN kyc_review.status IS 'Status';
COMMENT ON COLUMN kyc_review.due_date IS 'Due date';
COMMENT ON COLUMN kyc_review.assigned_to IS 'Analyst';
COMMENT ON COLUMN kyc_review.customer_outreach_at IS 'Time the customer was asked to update information';
COMMENT ON COLUMN kyc_review.outcome IS 'NO_CHANGE, UPDATED, EDD_REQUIRED, EXIT_RELATIONSHIP';
COMMENT ON COLUMN kyc_review.outcome_notes IS 'Notes';
COMMENT ON COLUMN kyc_review.completed_at IS 'Completion';
COMMENT ON COLUMN kyc_review.restrictions_applied IS 'Restrictions applied when overdue (e.g. debit block)';
COMMENT ON COLUMN kyc_review.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_review.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_review.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_review.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN kyc_review.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_kyc_review_tenant ON kyc_review (tenant_id, created_at);
CREATE INDEX ix_kyc_review_kyc_profile_id ON kyc_review (kyc_profile_id);
CREATE INDEX ix_kyc_review_customer_id ON kyc_review (customer_id);
CREATE INDEX ix_kyc_review_due_date ON kyc_review (due_date);
CREATE INDEX ix_kyc_review_assigned_to ON kyc_review (assigned_to);
ALTER TABLE kyc_review ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON kyc_review USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_kyc_review_touch BEFORE UPDATE ON kyc_review FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium); relayed rows stay for the replay window.
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  published_at    timestamptz
);
COMMENT ON COLUMN outbox.published_at IS 'When the relay published the event (NULL = pending). Relayed rows are kept for the replay window (meridian.events.retention.window) and then purged (MR-GAME-DAY)';
CREATE INDEX ix_outbox_pending ON outbox (created_at, id) WHERE published_at IS NULL;
CREATE INDEX ix_outbox_published ON outbox (published_at) WHERE published_at IS NOT NULL;
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA kyc TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA kyc TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA kyc GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
